mapper.select:
select * from ww_sys_auth a where 1=1

	and id = #{authId}

order by a.sort

select a.* from ww_sys_user u,ww_sys_user_role_ref urr,ww_sys_role r,ww_sys_role_auth_ref rar,ww_sys_auth a where u.login_name=urr.user_id and urr.role_id = r.role_id and r.role_id = rar.role_id and rar.auth_id = a.id and u.del_flag = '1' and r.del_flag='1'
and u.login_name = #{userId}
group by a.id,a.name,a.pid,a.data_module,a.sort,a.icon_class,a.data_filter_tags,a.requires_permissions order by a.sort
